let io;
function initReveal(){io?.disconnect();io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.12,rootMargin:'0px 0px -5% 0px'});$$('.rv').forEach(el=>RM?el.classList.add('in'):io.observe(el))}
let ticking=false;
function frame(){ticking=false;const y=scrollY,vh=innerHeight;$('#nav')?.classList.toggle('small',y>40);if(RM)return;
 const a=$('.athlete[data-par]');if(a)a.style.transform=`translateY(${(y*+a.dataset.par).toFixed(1)}px)`;
 const ck=$('#checkin');if(ck){const r=ck.getBoundingClientRect();if(r.bottom>0&&r.top<vh){const p=(vh-r.top)/(vh+r.height);$('#big1').style.transform=`translateX(${(-p*40).toFixed(2)}%)`;$('#big2').style.transform=`translateX(${(-30+p*30).toFixed(2)}%)`}}}
addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(frame)}},{passive:true});
