function route(){let h=(location.hash||'#home').slice(1)||'home';closeModal();$('#mm')?.classList.remove('open');
 if(JUMPS.includes(h)){const was=S.page==='home';if(!was)render('home');document.getElementById(h)?.scrollIntoView({behavior:was?'smooth':'instant',block:'start'});return}
 render(h);scrollTo(0,0)}
function render(h){S.timers.forEach(clearInterval);S.timers=[];S.onStore=null;if(h!=='scan')stopCam();loadMembers();
 let body,bind,cur=h,mode='';
 if(h==='classes'){body=pageClasses();bind=bindClasses}
 else if(h==='join'){body=pageJoin();bind=bindJoin}
 else if(h==='member'){body=pageMember();bind=bindMember}
 else if(h==='scan'){body=pageScan();bind=bindScan;mode='scan'}
 else if(h==='admin'){body=pageAdmin();bind=bindAdmin;mode='admin'}
 else if(h==='journal'){body=pageJournal();bind=bindJournal}
 else if(h.startsWith('article-')&&art(h.slice(8))){const a=art(h.slice(8));body=pageArticle(a);cur='journal'}
 else{h='home';cur='home';body=pageHome();bind=bindHome}
 S.page=h;document.title=({classes:'Classes',join:'Join',member:'Member area',scan:'Front desk',admin:'Admin',journal:'Journal'}[h]||'')+(h==='home'?'FORMA · Fitness & Recovery Club':' · FORMA');
 mount(cur,body,mode);bind&&bind();
 $$('[data-f]').forEach(a=>a.addEventListener('click',()=>{S.fil=a.dataset.f}));
 initReveal();frame()}
addEventListener('hashchange',route);
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a)return;const h=a.getAttribute('href').slice(1);if(location.hash==='#'+h){e.preventDefault();route()}});
route();
